        result.append(path[:])
        return
    for x in items:
        if x not in path:
            path.append(x)
            arrange(items, path, result)
            path.pop()

def permutations(items):
    result = []
    arrange(items, [], result)
    return result

print(permutations([1, 2, 3]))

def count_codes(n, path):
    if len(path) == n:
        return 1
    total = 0
    for bit in "01":
        last_is_one = path != [] and path[-1] == "1"
        if bit == "1" and last_is_one:
            continue
        path.append(bit)
        total += count_codes(n, path)
        path.pop()
    return total

print(count_codes(3, []))

