def safe(cols, c):
    r = len(cols)
    for i in range(r):
        if cols[i] == c or abs(cols[i] - c) == r - i:
            return False
    return True

def place(cols, n):
    if len(cols) == n:
        return 1
    total = 0
    for c in range(n):
        if safe(cols, c):
            cols.append(c)
            total += place(cols, n)
            cols.pop()
    return total

def count_queens(n):
    return place([], n)

print(count_queens(4))

def trace(grid, word, i, r, c):
    if i == len(word):
        return True
    if r < 0 or r >= len(grid):
        return False
    if c < 0 or c >= len(grid[0]):
        return False
    if grid[r][c] != word[i]:
        return False
    old = grid[r][c]
    grid[r][c] = "#"
    found = (trace(grid, word, i + 1, r - 1, c)
             or trace(grid, word, i + 1, r + 1, c)
             or trace(grid, word, i + 1, r, c - 1)
             or trace(grid, word, i + 1, r, c + 1))
    grid[r][c] = old
    return found

def has_word(grid, word):
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if trace(grid, word, 0, r, c):
                return True
    return False

grid = [
    ["c", "a", "t"],
    ["x", "r", "o"],
    ["d", "o", "g"],
]
print(has_word(grid, "car"))
